const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const bcrypt = require('bcrypt');

const app = express();
const UPLOAD_DIR = '/var/app/uploads';
const ALLOWED_EXTENSIONS = ['.txt', '.pdf', '.png', '.jpg'];

// Secure session store
const sessions = new Map();

// Authentication middleware
app.use(express.json());
app.use((req, res, next) => {
  const sessionId = req.headers['x-session-id'];
  if (!sessionId || !sessions.has(sessionId)) {
    if (req.path !== '/login') {
      return res.status(401).json({ error: 'Unauthorized' });
    }
  } else {
    req.user = sessions.get(sessionId);
  }
  next();
});

// Login endpoint with bcrypt
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }
  // Simulated user lookup
  const storedHash = await getStoredHash(username);
  if (!storedHash) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const valid = await bcrypt.compare(password, storedHash);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  const sessionId = crypto.randomBytes(32).toString('hex');
  sessions.set(sessionId, { username, role: await getUserRole(username) });
  res.json({ sessionId });
});

// File listing - shows user's files
