/**
 * Secure file download endpoint.
 * Uses path canonicalization to prevent directory traversal.
 * Validates file extension against allowlist.
 * Checks that resolved path is within user's upload directory.
 */
app.get('/files/:filename', (req, res) => {
  const filename = req.params.filename;

  // Validate extension
  const ext = path.extname(filename).toLowerCase();
  if (!ALLOWED_EXTENSIONS.includes(ext)) {
    return res.status(403).json({ error: 'File type not allowed' });
  }

  // Reject obvious traversal attempts
  if (filename.includes('..') || filename.includes('/') || filename.includes('\\')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  const userDir = path.resolve(UPLOAD_DIR, req.user.username);
  const filePath = path.resolve(userDir, filename);

  // Verify the resolved path is within the user's directory
  if (!filePath.startsWith(userDir + path.sep) && filePath !== userDir) {
    return res.status(403).json({ error: 'Access denied' });
  }

  // Security: verify file exists and is within bounds using realpath
  // This resolves symlinks to get the TRUE filesystem path
  fs.realpath(filePath, (err, resolvedPath) => {
    if (err) {
      return res.status(404).json({ error: 'File not found' });
    }

    // Check resolved path is still within user's specific directory
    const resolvedUserDir = path.resolve(UPLOAD_DIR, req.user.username);
    if (!resolvedPath.startsWith(resolvedUserDir + path.sep)) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Read using the RESOLVED path (after symlink resolution)
    fs.readFile(resolvedPath, (err, data) => {
      if (err) return res.status(500).json({ error: 'Read error' });
      res.setHeader('Content-Type', getMimeType(ext));
      res.setHeader('Content-Disposition', `attachment; filename="${path.basename(filename)}"`);
      res.send(data);
    });
  });
});

/**
 * File upload endpoint with size limits and type validation
 */
app.post('/files/:filename', (req, res) => {
  const filename = req.params.filename;
  const ext = path.extname(filename).toLowerCase();

  if (!ALLOWED_EXTENSIONS.includes(ext)) {
    return res.status(403).json({ error: 'File type not allowed' });
  }

  if (filename.includes('..') || filename.includes('/') || filename.includes('\\')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  // Only alphanumeric, dash, underscore, dot in filename
  if (!/^[a-zA-Z0-9_\-]+\.[a-z]{2,4}$/.test(filename)) {
    return res.status(400).json({ error: 'Invalid filename format' });
  }

  const userDir = path.resolve(UPLOAD_DIR, req.user.username);
  const filePath = path.join(userDir, filename);

  // Ensure user directory exists
  fs.mkdirSync(userDir, { recursive: true });

  const chunks = [];
  let totalSize = 0;
  const MAX_SIZE = 10 * 1024 * 1024; // 10MB

  req.on('data', (chunk) => {
    totalSize += chunk.length;
    if (totalSize > MAX_SIZE) {
      return res.status(413).json({ error: 'File too large' });
    }
    chunks.push(chunk);
  });

  req.on('end', () => {
    const data = Buffer.concat(chunks);
    fs.writeFile(filePath, data, (err) => {
      if (err) return res.status(500).json({ error: 'Write error' });
      res.json({ success: true, size: data.length });
    });
  });
});

// Admin endpoint - delete any user's file
app.delete('/admin/files/:username/:filename', (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Admin only' });
  }

  const { username, filename } = req.params;

  // Validate username against traversal (previously unvalidated)
  if (username.includes('..') || username.includes('/') || username.includes('\\')) {
    return res.status(400).json({ error: 'Invalid username' });
  }
  if (!/^[a-zA-Z0-9_\-]+$/.test(username)) {
    return res.status(400).json({ error: 'Invalid username format' });
  }

  if (filename.includes('..') || filename.includes('/') || filename.includes('\\')) {
    return res.status(400).json({ error: 'Invalid filename' });
  }

  const filePath = path.resolve(UPLOAD_DIR, username, filename);
  if (!filePath.startsWith(UPLOAD_DIR + path.sep)) {
    return res.status(403).json({ error: 'Access denied' });
  }

  fs.unlink(filePath, (err) => {
    if (err) return res.status(500).json({ error: 'Delete error' });
    res.json({ success: true });
  });
});

function getMimeType(ext) {
  const types = { '.txt': 'text/plain', '.pdf': 'application/pdf', '.png': 'image/png', '.jpg': 'image/jpeg' };
  return types[ext] || 'application/octet-stream';
}

async function getStoredHash(username) {
  // In production, this queries a database
  const users = { 'alice': '$2b$10$abcdefghijklmnopqrstuuABCDEFGHIJKLMNOPQRSTUVWXYZ012', 'admin': '$2b$10$xyzxyzxyzxyzxyzxyzxyzxyABCDEFGHIJKLMNOPQRSTUVWXYZ345' };
  return users[username] || null;
}

async function getUserRole(username) {
  const roles = { 'alice': 'user', 'admin': 'admin' };
  return roles[username] || 'user';
}

